/**
 * Infer `agent-sdk deploy` git source fields from a local checkout.
 *
 * From an agent directory inside a git repo with an `origin` remote, the
 * CLI can fill `--repo` / `--ref` / `--path` so `agent-sdk deploy` (no
 * flags) is enough. Explicit flags always win.
 */
import { execFile } from "node:child_process";
import { relative, resolve, sep } from "node:path";
import { promisify } from "node:util";
const execFileAsync = promisify(execFile);
const defaultGitRunner = async (args, cwd) => {
    try {
        const { stdout } = await execFileAsync("git", [...args], { cwd });
        const trimmed = stdout.trim();
        return trimmed === "" ? undefined : trimmed;
    }
    catch {
        return undefined;
    }
};
/**
 * Normalize a git remote URL to the https form the control plane accepts
 * (`https://host/owner/repo`, no `.git` suffix). Returns undefined for
 * unrecognized shapes.
 *
 * Accepts HTTPS, `git@host:path`, GitHub org-scoped SSH
 * (`org-123@github.com:owner/repo.git`), and `ssh://user@host[:port]/path`.
 */
export function httpsGitRepoUrlFromRemote(remote) {
    let url = remote.trim();
    if (url === "") {
        return undefined;
    }
    // SCP-like SSH: user@host:owner/repo(.git) — includes git@ and GitHub
    // org deploy keys (org-NNNN@github.com:…).
    const scpMatch = /^([^@/\s]+)@([^:/\s]+):(.+)$/.exec(url);
    if (scpMatch !== null) {
        const host = scpMatch[2];
        const path = scpMatch[3];
        url = `https://${host}/${path}`;
    }
    else if (/^ssh:\/\//i.test(url)) {
        // ssh://user@host[:port]/owner/repo → https://host/owner/repo
        try {
            const ssh = new URL(url);
            const path = ssh.pathname.replace(/^\/+/, "");
            if (ssh.hostname === "" || path === "") {
                return undefined;
            }
            url = `https://${ssh.hostname}/${path}`;
        }
        catch {
            return undefined;
        }
    }
    else if (!/^https?:\/\//i.test(url)) {
        return undefined;
    }
    let parsed;
    try {
        parsed = new URL(url);
    }
    catch {
        return undefined;
    }
    const path = parsed.pathname
        .replace(/\.git$/i, "")
        .replace(/\/+$/, "")
        .replace(/^\/+/, "");
    if (path === "" || !path.includes("/")) {
        return undefined;
    }
    // Use hostname (not host) so ssh://…@github.com:22/… does not keep :22.
    return `https://${parsed.hostname}/${path}`;
}
/**
 * Path of `dir` relative to `gitRoot`, using `/` separators. Undefined when
 * `dir` is outside the root; omitted (undefined) when `dir` *is* the root
 * so the control plane treats the agent as living at the repo root.
 */
export function agentPathRelativeToGitRoot(dir, gitRoot) {
    const absDir = resolve(dir);
    const absRoot = resolve(gitRoot);
    const rel = relative(absRoot, absDir);
    if (rel === "") {
        return undefined;
    }
    // Outside the repo (or a Windows drive mismatch) → cannot infer.
    if (rel.startsWith("..") || rel.split(sep).includes("..")) {
        return undefined;
    }
    return rel.split(sep).join("/");
}
/**
 * Probe the git checkout containing `dir` for deploy source fields.
 * Missing pieces stay undefined.
 */
export async function inferDeployGitSource(dir, options) {
    const git = options?.git ?? defaultGitRunner;
    const absDir = resolve(dir);
    const gitRoot = await git(["rev-parse", "--show-toplevel"], absDir);
    if (gitRoot === undefined) {
        return {};
    }
    const remote = await git(["remote", "get-url", "origin"], gitRoot);
    const gitRepoUrl = remote === undefined ? undefined : httpsGitRepoUrlFromRemote(remote);
    const branch = await git(["rev-parse", "--abbrev-ref", "HEAD"], gitRoot);
    let gitRef;
    if (branch !== undefined && branch !== "HEAD") {
        gitRef = branch;
    }
    else {
        // Detached HEAD — pin the exact commit so the control plane still
        // has something concrete to build.
        gitRef = await git(["rev-parse", "HEAD"], gitRoot);
    }
    const agentPath = agentPathRelativeToGitRoot(absDir, gitRoot);
    return {
        gitRepoUrl,
        gitRef,
        agentPath,
    };
}
